public:
    Deposito(Capacidad capacidad, Existencias existencias)
        : capacidad_{capacidad.unidades}, existencias_{existencias.unidades} {
        if (capacidad_ < 1 || capacidad_ > 20 || existencias_ < 0 || existencias_ > capacidad_) {
            throw DepositoInvalido{};
        }
    }
    int capacidad() const { return capacidad_; }
    int existencias() const { return existencias_; }
    int disponibles() const { return capacidad_ - existencias_; }
    bool agregar(int cantidad) {
