        existencias_ -= cantidad;
        return true;
    }
private:
    int capacidad_;
    int existencias_;
};

enum class Accion { agregar, retirar };
struct Movimiento { Accion accion; int cantidad; };

int main() {
    Deposito deposito{Capacidad{6}, Existencias{1}};
    std::vector<Movimiento> movimientos{{Accion::agregar, 4}, {Accion::retirar, 2},
        {Accion::retirar, 5}, {Accion::agregar, 3}, {Accion::agregar, 0}};
    for (const auto& movimiento : movimientos) {
        bool aceptado = false;
        if (movimiento.accion == Accion::agregar) {
            aceptado = deposito.agregar(movimiento.cantidad);
        } else {
            aceptado = deposito.retirar(movimiento.cantidad);
        }
        std::cout << aceptado << ":" << deposito.existencias() << ";";
    }
    return 0;
}
